/* symbols.h - glyph presets (upstream omp symbols.ts: "unicode" | "nerd" | "ascii"), embedded from
 * assets/tui/symbols.json (generated by build-tools/extract_symbols.py from the upstream source). */
#ifndef OMC_TUI_SYMBOLS_H
#define OMC_TUI_SYMBOLS_H

#include "core/core.h"

/* glyph for an upstream symbol key ("boxRound.topLeft", "status.success", "sep.powerline", ...) in the
 * active preset; "" for unknown keys. Returned strings live for the process. */
const char *tui_sym(const char *key);
/* "unicode" (default), "nerd" or "ascii"; returns false for an unknown preset */
bool tui_sym_set_preset(const char *preset);
const char *tui_sym_preset(void);
/* spinner frames of the active preset; type is "status" or "activity". Returns frame count. */
size_t tui_sym_spinner(const char *type, const char *const **frames);

#endif
